 E(24.5,33+hy,8.6,7.6,'x');E(24,32.5+hy,8.1,7.1,'w');
 [[17,36],[19.2,39],[22,40.3],[25,40.8],[28,39.8],[31,37.2]].forEach(function(f){E(f[0],f[1]+hy,1.7,1.7,'w')});
